// Montserrat (SIL Open Font License 1.1) and Roboto (Apache License 2.0),
// latin subsets only, inlined as base64.
//
// Embedded rather than linked because the report is rendered by headless
// Chrome via page.setContent(), which gives no guarantee a webfont fetch
// finishes before the PDF is taken — and because a font the SERVER happens to
// have installed is not a design. Without this the PDF silently fell back to
// whatever the host had (Segoe UI on a Windows dev box, something else on a
// Linux host), which changes text metrics, line breaks, and therefore where
// every page break lands. Inlining makes the output identical anywhere.
//
// Only the weights the report actually uses are here. Adding one costs roughly
// 40KB of base64 on every render, so add deliberately.
export const REPORT_FONT_FACES = "@font-face{font-family:\"Montserrat\";font-style:normal;font-weight:600;font-display:block;src:url(data:font/woff2;base64,) format(\"woff2\")}\n@font-face{font-family:\"Montserrat\";font-style:normal;font-weight:700;font-display:block;src:url(data:font/woff2;base64,) format(\"woff2\")}\n@font-face{font-family:\"Roboto\";font-style:italic;font-weight:400;font-display:block;src:url(data:font/woff2;base64,) format(\"woff2\")}\n@font-face{font-family:\"Roboto\";font-style:normal;font-weight:400;font-display:block;src:url(data:font/woff2;base64,) format(\"woff2\")}\n@font-face{font-family:\"Roboto\";font-style:normal;font-weight:500;font-display:block;src:url(data:font/woff2;base64,) format(\"woff2\")}";
